def search_kb(q: str, limit: int = 20) -> list[dict]:
    q = (q or "").lower()
    if not q:
        return ARTICLES[:limit]
    hit = [a for a in ARTICLES if q in a["title"].lower() or q in a["body"].lower() or q in ",".join(a["tags"])]
    return hit[:limit]
